<?php
declare(strict_types=1);
session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Strict','cookie_secure'=>!empty($_SERVER['HTTPS'])]);
require dirname(__DIR__) . '/src/bootstrap.php';

if (isset($_GET['logout'])) { session_destroy(); header('Location: ./'); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['email'],$_POST['password'])) {
    if (hash_equals(envv('ADMIN_EMAIL','')??'',trim($_POST['email'])) && password_verify($_POST['password'],envv('ADMIN_PASSWORD_HASH','')??'')) {
        session_regenerate_id(true); $_SESSION['admin']=true; header('Location: ./'); exit;
    }
    $loginError='E-posta veya parola hatalı.';
}
if (empty($_SESSION['admin'])) { ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/admin.css"><title>Şut ve Gol Yönetim</title></head><body class="login"><main class="login-card"><div class="brand"><span class="brand-mark">↗</span><div><b>ŞUT VE GOL</b><small>Yönetim merkezi</small></div></div><h1>Tekrar hoş geldin</h1><p>Oyuncuları, skorları ve oyun sağlığını izle.</p><?php if(isset($loginError)):?><div class="alert"><?=htmlspecialchars($loginError)?></div><?php endif?><form method="post"><label>E-posta<input name="email" type="email" autocomplete="username" required></label><label>Parola<input name="password" type="password" autocomplete="current-password" required></label><button>Giriş yap</button></form></main></body></html><?php exit; }

$range=max(7,min(90,(int)($_GET['days']??30)));
$stats=db()->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM users WHERE created_at>=DATE_SUB(NOW(),INTERVAL $range DAY)) new_users,(SELECT COUNT(DISTINCT user_id) FROM game_sessions WHERE started_at>=DATE_SUB(NOW(),INTERVAL 1 DAY)) dau,(SELECT COUNT(*) FROM game_sessions WHERE started_at>=DATE_SUB(NOW(),INTERVAL $range DAY)) sessions,(SELECT COALESCE(SUM(duration_ms),0) FROM game_sessions WHERE finished_at>=DATE_SUB(NOW(),INTERVAL $range DAY)) play_ms,(SELECT COALESCE(AVG(score),0) FROM game_sessions WHERE suspicious=0 AND finished_at>=DATE_SUB(NOW(),INTERVAL $range DAY)) avg_score,(SELECT COUNT(*) FROM game_sessions WHERE suspicious=1 AND started_at>=DATE_SUB(NOW(),INTERVAL $range DAY)) suspicious")->fetch();
$trend=db()->query("SELECT DATE(started_at) day,COUNT(*) sessions,COUNT(DISTINCT user_id) players,ROUND(AVG(IF(suspicious=0,score,NULL))) avg_score FROM game_sessions WHERE started_at>=DATE_SUB(CURDATE(),INTERVAL $range DAY) GROUP BY DATE(started_at) ORDER BY day")->fetchAll();
$providers=db()->query('SELECT provider,COUNT(*) total FROM identities GROUP BY provider ORDER BY total DESC')->fetchAll();
$leaders=db()->query("SELECT u.username,MAX(g.score) score,COUNT(*) games,MAX(g.finished_at) last_game FROM users u JOIN game_sessions g ON g.user_id=u.id WHERE g.suspicious=0 AND g.finished_at IS NOT NULL GROUP BY u.id ORDER BY score DESC LIMIT 10")->fetchAll();
$recent=db()->query('SELECT g.public_id,u.username,g.score,g.shots,g.hits,g.duration_ms,g.stage,g.suspicious,g.reject_reason,g.finished_at FROM game_sessions g JOIN users u ON u.id=g.user_id WHERE g.finished_at IS NOT NULL ORDER BY g.finished_at DESC LIMIT 20')->fetchAll();
$max=max(1,...array_column($trend,'sessions'));
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/admin.css"><title>Şut ve Gol Yönetim</title></head><body><aside><div class="brand"><span class="brand-mark">↗</span><div><b>ŞUT VE GOL</b><small>Yönetim merkezi</small></div></div><nav><a class="active" href="./">Genel bakış</a><a href="#liderler">Liderler</a><a href="#oturumlar">Oturumlar</a><a href="?logout=1">Çıkış</a></nav></aside><main class="dashboard"><header><div><p class="eyebrow">CANLI OYUN VERİSİ</p><h1>Genel bakış</h1><p>Oyuncu büyümesi ve oyun kalitesi tek ekranda.</p></div><form><select name="days" onchange="this.form.submit()"><option value="7" <?=$range===7?'selected':''?>>Son 7 gün</option><option value="30" <?=$range===30?'selected':''?>>Son 30 gün</option><option value="90" <?=$range===90?'selected':''?>>Son 90 gün</option></select></form></header><section class="metrics"><article><span>Toplam oyuncu</span><strong><?=number_format((int)$stats['users'])?></strong><small>+<?=number_format((int)$stats['new_users'])?> yeni</small></article><article><span>Günlük aktif</span><strong><?=number_format((int)$stats['dau'])?></strong><small>Son 24 saat</small></article><article><span>Oyun oturumu</span><strong><?=number_format((int)$stats['sessions'])?></strong><small><?=round((int)$stats['play_ms']/3600000,1)?> saat oynanış</small></article><article><span>Ortalama skor</span><strong><?=number_format((float)$stats['avg_score'],0)?></strong><small class="<?=+$stats['suspicious']?'warn':''?>"><?=number_format((int)$stats['suspicious'])?> şüpheli kayıt</small></article></section><section class="grid"><article class="panel chart"><div class="panel-title"><div><p class="eyebrow">ETKİLEŞİM</p><h2>Günlük oturumlar</h2></div></div><div class="bars"><?php foreach($trend as $row):?><div class="bar-wrap" title="<?=e($row['day'])?>: <?=e($row['sessions'])?> oturum"><div class="bar" style="height:<?=max(4,round(180*$row['sessions']/$max))?>px"></div><small><?=date('d.m',strtotime($row['day']))?></small></div><?php endforeach?></div></article><article class="panel"><p class="eyebrow">ÜYELİK</p><h2>Giriş sağlayıcıları</h2><div class="provider-list"><?php foreach($providers as $p):?><div><span><?=e(ucfirst($p['provider']))?></span><strong><?=number_format((int)$p['total'])?></strong></div><?php endforeach?></div></article></section><section class="grid" id="liderler"><article class="panel"><p class="eyebrow">REKABET</p><h2>İlk 10 oyuncu</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Kullanıcı</th><th>Rekor</th><th>Oyun</th></tr></thead><tbody><?php foreach($leaders as $i=>$u):?><tr><td><span class="rank"><?=$i+1?></span></td><td>@<?=e($u['username'])?></td><td><b><?=number_format((int)$u['score'])?></b></td><td><?=number_format((int)$u['games'])?></td></tr><?php endforeach?></tbody></table></div></article><article class="panel" id="oturumlar"><p class="eyebrow">DENETİM</p><h2>Son oyunlar</h2><div class="table-wrap"><table><thead><tr><th>Kullanıcı</th><th>Skor</th><th>İsabet</th><th>Durum</th></tr></thead><tbody><?php foreach($recent as $g):?><tr><td>@<?=e($g['username'])?><small><?=e($g['stage'])?></small></td><td><b><?=number_format((int)$g['score'])?></b></td><td><?=e($g['hits'])?>/<?=e($g['shots'])?></td><td><span class="status <?=$g['suspicious']?'bad':'good'?>"><?=$g['suspicious']?'Şüpheli':'Onaylı'?></span></td></tr><?php endforeach?></tbody></table></div></article></section></main></body></html>
